1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import MinecraftGame from "@/components/MinecraftGame";
5	import AccountProfileSelect from "@/components/menu/AccountProfileSelect";
6	import AuthScreen from "@/components/menu/AuthScreen";
7	import OnlineWorldSelect from "@/components/menu/OnlineWorldSelect";
8	import ProfileSelect from "@/components/menu/ProfileSelect";
9	import WelcomeScreen from "@/components/menu/WelcomeScreen";
10	import WorldSelect from "@/components/menu/WorldSelect";
11	import { currentUser, onlineUsed, type OnlineUser } from "@/lib/auth/client";
12	import { migrateLegacySave } from "@/lib/game/legacyMigration";
13	import { DEFAULT_SKIN_ID, isSkinId } from "@/lib/game/playerSkins";
14	import { getProfile, setActiveProfile, type Profile } from "@/lib/game/profiles";
15	import { createWorld, deleteWorld, getWorld, touchWorld, worldSaveKey, type WorldMeta } from "@/lib/game/worlds";
16	import { writeSave } from "@/lib/game/save";
17	import { pullCloudSaveIfNewer } from "@/lib/game/cloudSaves";
18	import { deleteOnlineWorld, requestJoinTicket, type OnlineWorld } from "@/lib/online/onlineClient";
19	import type { OnlineProfile } from "@/lib/online/profilesClient";
20	import { connectNetworkSession, type NetworkSession } from "@/lib/net/NetworkSession";
21	import { installUiTiles } from "@/lib/ui/chromeTiles";
22	
23	/**
24	 * Top-level menu shell. Owns the screen state machine — logged out it roots at
25	 * the welcome gate (sign in via the dedicated auth screen, or play locally:
26	 * welcome -> auth | profile-select -> world-select -> play), while a signed-in
27	 * session skips the gate straight to the account home — and boots the legacy
28	 * migration once on mount. The play screen mounts MinecraftGame keyed by world
29	 * id + a reload nonce, so switching worlds (or Load/Reset) remounts the
30	 * subtree — the game effect's cleanup disposes the old engine/renderer and a
31	 * fresh mount boots the next world, with no page reload.
32	 */
33	type Screen =
34	  // The logged-out root: choose an online account or local (browser) play.
35	  | { name: "welcome" }
36	  // The dedicated sign-in / register screen behind the gate's "Sign in".
37	  | { name: "auth" }
38	  | { name: "profile-select" }
39	  | { name: "world-select"; profileId: string }
40	  | { name: "online-worlds"; profile: OnlineProfile }
41	  | { name: "play"; profileId: string; worldId: string }
42	  // An account profile's singleplayer (sp-cloud) world: full local engine, no
43	  // game server — the save syncs to the account as a cloud blob.
44	  | { name: "play-cloud"; profile: OnlineProfile; world: OnlineWorld }
45	  // play-online carries the play-usable identity derived from the account
46	  // profile, plus that profile itself so "quit to worlds" returns to its list.
47	  | { name: "play-online"; profile: Profile; world: OnlineWorld; session: NetworkSession; onlineProfile: OnlineProfile };
48	
49	/** A play-usable Profile from a server-side account profile (skin sanitized). */
50	function profileFromOnline(profile: OnlineProfile): Profile {
51	  return { id: profile.id, name: profile.name, skinId: isSkinId(profile.skinId) ? profile.skinId : DEFAULT_SKIN_ID, createdAt: 0 };
52	}
53	
54	/**
55	 * An account singleplayer world's meta: the `cloud:` id keys this device's
56	 * localStorage save cache, and `cloudId` makes the game hook's autosave sync
57	 * push every save up to the account blob.
58	 */
59	function cloudWorldMeta(world: OnlineWorld, profileId: string): WorldMeta {
60	  return { ...onlineWorldMeta(world, profileId), id: `cloud:${world.id}`, cloudId: world.id };
61	}
62	
63	/** Online worlds mount the same game subtree; the meta is a projection of the server row. */
64	function onlineWorldMeta(world: OnlineWorld, profileId: string): WorldMeta {
65	  return {
66	    id: `online:${world.id}`,
67	    profileId,
68	    name: world.name,
69	    seed: world.seed,
70	    worldType: world.worldType as WorldMeta["worldType"],
71	    gameMode: world.gameMode as WorldMeta["gameMode"],
72	    difficulty: world.difficulty as WorldMeta["difficulty"],
73	    hardcore: world.hardcore,
74	    worldgenVersion: world.worldgenVersion,
75	    createdAt: 0,
76	    lastPlayedAt: 0
77	  };
78	}
79	
80	/**
81	 * Remembers the world being played for this tab so a reload resumes it instead
82	 * of dropping back to the menu. sessionStorage (not localStorage) so a brand-new
83	 * tab still cold-starts at profile-select.
84	 */
85	const SESSION_KEY = "monecraft_active_session";
86	
87	/** How long the welcome gate may wait on the session probe before showing. */
88	const AUTH_PROBE_TIMEOUT_MS = 4000;
89	
90	function readSessionPointer(): { profileId: string; worldId: string } | null {
91	  try {
92	    const raw = sessionStorage.getItem(SESSION_KEY);
93	    if (!raw) return null;
94	    const parsed = JSON.parse(raw) as { profileId?: unknown; worldId?: unknown };
95	    if (typeof parsed?.profileId === "string" && typeof parsed?.worldId === "string") {
96	      return { profileId: parsed.profileId, worldId: parsed.worldId };
97	    }
98	    return null;
99	  } catch {
100	    return null;
101	  }
102	}
103	
104	function writeSessionPointer(pointer: { profileId: string; worldId: string } | null): void {
105	  try {
106	    if (pointer) sessionStorage.setItem(SESSION_KEY, JSON.stringify(pointer));
107	    else sessionStorage.removeItem(SESSION_KEY);
108	  } catch {
109	    // No resume across reload if sessionStorage is unavailable — never fatal.
110	  }
111	}
112	
113	export default function GameShell() {
114	  const [ready, setReady] = useState(false);
115	  const [screen, setScreen] = useState<Screen>({ name: "welcome" });
116	  const [reloadNonce, setReloadNonce] = useState(0);
117	  const [connecting, setConnecting] = useState<string | null>(null);
118	  const [connectError, setConnectError] = useState<string | null>(null);
119	  // A join is in flight — guards against a double-click opening (and leaking) a
120	  // second socket. A ref, not `connecting`, so it's set synchronously.
121	  const joiningRef = useRef(false);
122	  // The signed-in account (its presence flips the menu into account mode).
123	  // Offline-first: never asked until this browser went online.
124	  const [onlineUser, setOnlineUser] = useState<OnlineUser | null>(null);
125	  // The local-worlds door: a signed-in account browsing its local (browser)
126	  // profiles/worlds — where cloud-save sync lives — without signing out.
127	  const [browsingLocal, setBrowsingLocal] = useState(false);
128	  // True once the mount-time session probe has answered (or was skipped) —
129	  // the welcome gate holds a neutral frame until then, so a signed-in reload
130	  // lands straight on the account home with no gate flash.
131	  const [authProbed, setAuthProbed] = useState(false);
132	  const refreshOnlineUser = useCallback(() => {
133	    if (!onlineUsed()) {
134	      // Pure-local browser: nothing to probe. Microtask hop keeps the set off
135	      // the synchronous effect path (cascading-render lint).
136	      queueMicrotask(() => setAuthProbed(true));
137	      return;
138	    }
139	    // A hung probe (stalled fetch, dead proxy) must not strand the gate on the
140	    // neutral frame: reveal it at the deadline and treat the visitor as logged
141	    // out — a probe that settles later still flips into account mode.
142	    const deadline = setTimeout(() => setAuthProbed(true), AUTH_PROBE_TIMEOUT_MS);
143	    void currentUser().then(
144	      (user) => {
145	        clearTimeout(deadline);
146	        setOnlineUser(user);
147	        if (!user) setBrowsingLocal(false); // signed out: the door has no "back"
148	        setAuthProbed(true);
149	      },
150	      () => {
151	        clearTimeout(deadline);
152	        setAuthProbed(true); // probe failed (offline): treat as logged out
153	      }
154	    );
155	  }, []);
156	
157	  /**
158	   * Open a world for play. A cloud-linked one (WorldMeta.cloudId) reconciles
159	   * first: pull the remote save if it advanced past this device's cursor, write
160	   * it to disk, and boot from disk like any other world — reusing the "Opening…"
161	   * gate. The caller owns the `joiningRef` guard (this helper does not), so the
162	   * materialize-then-open path can hold it across `createWorld` too.
163	   */
164	  const openWorld = async (profileId: string, worldId: string) => {
165	    const world = getWorld(worldId);
166	    touchWorld(worldId);
167	    writeSessionPointer({ profileId, worldId });
168	    if (world?.cloudId) {
169	      setConnecting(world.name);
170	      try {
171	        const decision = await pullCloudSaveIfNewer(world.cloudId);
172	        if (decision.adopt) writeSave(worldSaveKey(worldId), decision.save);
173	      } catch {
174	        // Offline or a bad blob → fall through and play the local copy.
175	      } finally {
176	        setConnecting(null);
177	      }
178	    }
179	    setScreen({ name: "play", profileId, worldId });
180	  };
181	
182	  const playLocal = async (profileId: string, worldId: string) => {
183	    if (joiningRef.current) return;
184	    joiningRef.current = true;
185	    try {
186	      await openWorld(profileId, worldId);
187	    } finally {
188	      joiningRef.current = false;
189	    }
190	  };
191	
192	  /**
193	   * Open an account singleplayer world: reconcile this device's save cache
194	   * with the cloud blob (adopt the remote only when it advanced past our
195	   * cursor), then boot the full local engine — no game server involved.
196	   * Unlike local worlds there is no manifest entry and no session-resume
197	   * pointer; a reload lands back on the menu (like play-online).
198	   */
199	  const playCloud = async (profile: OnlineProfile, world: OnlineWorld) => {
200	    if (joiningRef.current) return;
201	    joiningRef.current = true;
202	    setConnecting(world.name);
203	    try {
204	      const decision = await pullCloudSaveIfNewer(world.id);
205	      if (decision.adopt) writeSave(worldSaveKey(`cloud:${world.id}`), decision.save);
206	    } catch {
207	      // Offline or a bad blob → play this device's cache (or a fresh world).
208	    } finally {
209	      setConnecting(null);
210	      joiningRef.current = false;
211	    }
212	    setScreen({ name: "play-cloud", profile, world });
213	  };
214	
215	  /** Materialize a cloud save as a local world (linked by cloudId), then open it — the pull-on-open fills it in. */
216	  const downloadCloud = async (profileId: string, world: OnlineWorld) => {
217	    // Guard BEFORE createWorld so a fast double-click can't persist two local
218	    // worlds sharing the same cloudId (the second open would just be dropped).
219	    if (joiningRef.current) return;
220	    joiningRef.current = true;
221	    try {
222	      const local = createWorld(profileId, world.name, String(world.seed), {
223	        worldType: world.worldType as WorldMeta["worldType"],
224	        gameMode: world.gameMode as WorldMeta["gameMode"],
225	        difficulty: world.difficulty as WorldMeta["difficulty"],
226	        hardcore: world.hardcore,
227	        worldgenVersion: world.worldgenVersion,
228	        cloudId: world.id
229	      });
230	      await openWorld(profileId, local.id);
231	    } finally {
232	      joiningRef.current = false;
233	    }
234	  };
235	
236	  /** Account profile → ticket → socket → replica sync → play. The profile's id
237	   *  rides the ticket so the roster shows that profile's name and skin. */
238	  const playOnline = async (profile: Profile, world: OnlineWorld, onlineProfile: OnlineProfile) => {
239	    if (joiningRef.current) return; // a join is already in flight
240	    joiningRef.current = true;
241	    setConnectError(null);
242	    setConnecting(world.name);
243	    const ticketProfileId = onlineProfile.id;
244	    try {
245	      // No sign-in pre-check: this is only reachable from account mode, and an
246	      // expired session just fails the ticket mint into the dialog below.
247	      const grant = await requestJoinTicket(world.id, ticketProfileId);
248	      if (!grant) throw new Error("could not get a join ticket — are you still signed in, and is the game server configured?");
249	      // The reconnect ladder mints a fresh short-lived ticket each retry — the
250	      // 60 s TTL means a stale one is useless a minute after a drop.
251	      const session = await connectNetworkSession(grant.gameServerUrl, grant.ticket, undefined, {
252	        reconnect: async () => {
253	          const next = await requestJoinTicket(world.id, ticketProfileId);
254	          return next ? { url: next.gameServerUrl, ticket: next.ticket } : null;
255	        }
256	      });
257	      setScreen({ name: "play-online", profile, world, session, onlineProfile });
258	    } catch (error) {
259	      setConnectError(error instanceof Error ? error.message : "connection failed");
260	    } finally {
261	      setConnecting(null);
262	      joiningRef.current = false;
263	    }
264	  };
265	
266	  useEffect(() => {
267	    installUiTiles(); // the menu chrome shares the in-game noise tiles
268	    migrateLegacySave();
269	    // Resume the tab's world if one was being played and still exists.
270	    const pointer = readSessionPointer();
271	    const resume: Screen | null =
272	      pointer && getProfile(pointer.profileId) && getWorld(pointer.worldId) ? { name: "play", profileId: pointer.profileId, worldId: pointer.worldId } : null;
273	    // Microtask hop keeps this off the synchronous effect path (cascading-render lint).
274	    queueMicrotask(() => {
275	      if (resume) {
276	        setScreen(resume);
277	        // A resumed local world means the player came through the local menus —
278	        // quitting should walk back out through them, even for a signed-in
279	        // account, not jump abruptly to the account home.
280	        setBrowsingLocal(true);
281	      }
282	      setReady(true);
283	    });
284	  }, []);
285	
286	  // Discover an existing account session so a signed-in reload lands in account
287	  // mode (offline-first: refreshOnlineUser no-ops until this browser went online).
288	  useEffect(() => refreshOnlineUser(), [refreshOnlineUser]);
289	
290	  // The "Opening…" gate and join-failure dialog, shared by both world lists.
291	  const netModals = (
292	    <>
293	      {connecting && (
294	        <div className="net-modal" role="status">
295	          <div className="net-modal-box">Opening “{connecting}”…</div>
296	        </div>
297	      )}
298	      {connectError && (
299	        <div className="net-modal" role="alertdialog" aria-label="Connection failed">
300	          <div className="net-modal-box">
301	            <p>Couldn&apos;t join: {connectError}</p>
302	            <button type="button" className="mc-button" onClick={() => setConnectError(null)}>
303	              OK
304	            </button>
305	          </div>
306	        </div>
307	      )}
308	    </>
309	  );
310	
311	  // localStorage is read below; hold the neutral frame until we're client-side.
312	  if (!ready) return <div className="menu-screen" />;
313	
314	  if (screen.name === "play") {
315	    const profile = getProfile(screen.profileId);
316	    const world = getWorld(screen.worldId);
317	    // Both exist in normal flow; a cross-tab delete drops us back to a menu.
318	    if (profile && world) {
319	      return (
320	        <MinecraftGame
321	          key={`${world.id}:${reloadNonce}`}
322	          world={world}
323	          profile={profile}
324	          onQuitToWorlds={() => {
325	            writeSessionPointer(null);
326	            setScreen({ name: "world-select", profileId: profile.id });
327	          }}
328	          onDeleteWorld={() => {
329	            deleteWorld(world.id); // hardcore Game Over: erase the dead world and leave
330	            writeSessionPointer(null);
331	            setScreen({ name: "world-select", profileId: profile.id });
332	          }}
333	          onReloadWorld={() => setReloadNonce((nonce) => nonce + 1)}
334	        />
335	      );
336	    }
337	  }
338	
339	  if (screen.name === "play-cloud") {
340	    const backToWorlds: Screen = { name: "online-worlds", profile: screen.profile };
341	    return (
342	      <MinecraftGame
343	        key={`cloud:${screen.world.id}:${reloadNonce}`}
344	        world={cloudWorldMeta(screen.world, screen.profile.id)}
345	        profile={profileFromOnline(screen.profile)}
346	        onQuitToWorlds={() => setScreen(backToWorlds)}
347	        onDeleteWorld={() => {
348	          // Hardcore game-over: delete the cloud world (row + blob), then this
349	          // device's save cache — only after the server confirmed, so a failed
350	          // delete (offline) leaves a still-playable world in the list rather
351	          // than a hollow one that re-downloads its own game-over.
352	          void deleteOnlineWorld(screen.world.id).then((deleted) => {
353	            if (!deleted) return;
354	            try {
355	              localStorage.removeItem(worldSaveKey(`cloud:${screen.world.id}`));
356	            } catch {
357	              // Cache cleanup only — never fatal.
358	            }
359	          });
360	          setScreen(backToWorlds);
361	        }}
362	        onReloadWorld={() => setReloadNonce((nonce) => nonce + 1)}
363	      />
364	    );
365	  }
366	
367	  if (screen.name === "play-online") {
368	    // Quit returns to the account profile's online worlds.
369	    const backToWorlds: Screen = { name: "online-worlds", profile: screen.onlineProfile };
370	    return (
371	      <MinecraftGame
372	        key={`online:${screen.world.id}`}
373	        world={onlineWorldMeta(screen.world, screen.profile.id)}
374	        profile={screen.profile}
375	        online={screen.session}
376	        onQuitToWorlds={() => setScreen(backToWorlds)}
377	        onDeleteWorld={() => {
378	          // Hardcore game-over: actually delete the shared world on the server
379	          // (owner-gated; a member just leaves), then return to the list.
380	          screen.session.dispose();
381	          void deleteOnlineWorld(screen.world.id);
382	          setScreen(backToWorlds);
383	        }}
384	        onReloadWorld={() => setScreen(backToWorlds)}
385	      />
386	    );
387	  }
388	
389	  if (screen.name === "world-select") {
390	    const profile = getProfile(screen.profileId);
391	    if (profile) {
392	      return (
393	        <>
394	          <WorldSelect
395	            profile={profile}
396	            onPlay={(worldId) => void playLocal(profile.id, worldId)}
397	            onDownloadCloud={(world) => void downloadCloud(profile.id, world)}
398	            cloudEnabled={onlineUser !== null}
399	            onBack={() => setScreen({ name: "profile-select" })}
400	          />
401	          {netModals}
402	        </>
403	      );
404	    }
405	  }
406	
407	  if (screen.name === "online-worlds") {
408	    return (
409	      <>
410	        <OnlineWorldSelect
411	          profile={screen.profile}
412	          onPlayOnline={(world) => void playOnline(profileFromOnline(screen.profile), world, screen.profile)}
413	          onPlayCloud={(world) => void playCloud(screen.profile, world)}
414	          onBack={() => setScreen({ name: "profile-select" })}
415	        />
416	        {netModals}
417	      </>
418	    );
419	  }
420	
421	  // The root menus are auth-aware: a signed-in account gets its account home
422	  // (unless it stepped through the local-worlds door), a logged-out visitor
423	  // roots at the welcome gate — sign in on the dedicated screen, or browse the
424	  // local (browser) profiles.
425	  const accountMode = onlineUser !== null;
426	  if (accountMode && !browsingLocal) {
427	    return (
428	      <AccountProfileSelect
429	        user={onlineUser}
430	        onPlay={(profile) => setScreen({ name: "online-worlds", profile })}
431	        onPlayLocally={() => {
432	          // Set the screen too: it may still read "welcome"/"auth", which
433	          // would bounce the door back to the gate instead of the local list.
434	          setBrowsingLocal(true);
435	          setScreen({ name: "profile-select" });
436	        }}
437	        onSignedOut={() => {
438	          setOnlineUser(null);
439	          setScreen({ name: "welcome" }); // sign-out lands on the gate
440	        }}
441	      />
442	    );
443	  }
444	
445	  if (screen.name === "auth") {
446	    return <AuthScreen onAuthChange={refreshOnlineUser} onBack={() => setScreen({ name: "welcome" })} />;
447	  }
448	
449	  if (screen.name === "welcome") {
450	    // Hold the neutral frame until the session probe answers — a signed-in
451	    // reload goes straight to the account home above, never a gate flash.
452	    if (!authProbed) return <div className="menu-screen" />;
453	    return <WelcomeScreen onSignIn={() => setScreen({ name: "auth" })} onPlayLocally={() => setScreen({ name: "profile-select" })} />;
454	  }
455	
456	  return (
457	    <ProfileSelect
458	      onPlay={(profileId) => {
459	        setActiveProfile(profileId);
460	        setScreen({ name: "world-select", profileId });
461	      }}
462	      onBackToAccount={accountMode ? () => setBrowsingLocal(false) : undefined}
463	      onBackToWelcome={accountMode ? undefined : () => setScreen({ name: "welcome" })}
464	    />
465	  );
466	}
