/* Probes whether an IndexedDB put started inside pagehide / visibilitychange
 * (hidden) commits across a page.reload() in headless Chromium. */
import { chromium } from "playwright";

const browser = await chromium.launch();
const page = await browser.newPage();
await page.route("http://probe.test/**", (route) => route.fulfill({ contentType: "text/html", body: "<!doctype html><title>probe</title>" }));
await page.goto("http://probe.test/");

await page.evaluate(async () => {
  const open = indexedDB.open("probe", 1);
  await new Promise<void>((resolve, reject) => {
    open.onupgradeneeded = () => open.result.createObjectStore("s");
    open.onsuccess = () => resolve();
    open.onerror = () => reject(open.error);
  });
  const db = open.result;
  const fired: string[] = [];
  (window as any).__fired = fired;
  window.addEventListener("pagehide", () => {
    fired.push("pagehide");
    try {
      db.transaction("s", "readwrite").objectStore("s").put("from-pagehide", "ph");
      localStorage.setItem("probe_ph_started", "1");
    } catch (e) {
      localStorage.setItem("probe_ph_started", "threw:" + String(e));
    }
  });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState !== "hidden") return;
    fired.push("vis-hidden");
    try {
      db.transaction("s", "readwrite").objectStore("s").put("from-vis", "vis");
      localStorage.setItem("probe_vis_started", "1");
    } catch (e) {
      localStorage.setItem("probe_vis_started", "threw:" + String(e));
    }
  });
});

await page.reload();

const result = await page.evaluate(async () => {
  const open = indexedDB.open("probe", 1);
  await new Promise<void>((resolve) => {
    open.onsuccess = () => resolve();
  });
  const db = open.result;
  const get = (key: string) =>
    new Promise((resolve) => {
      const req = db.transaction("s").objectStore("s").get(key);
      req.onsuccess = () => resolve(req.result ?? null);
      req.onerror = () => resolve("get-error");
    });
  return {
    pagehideRecord: await get("ph"),
    visRecord: await get("vis"),
    pagehideStarted: localStorage.getItem("probe_ph_started"),
    visStarted: localStorage.getItem("probe_vis_started")
  };
});

console.log(JSON.stringify(result, null, 2));
await browser.close();

