/* Compares unload triggers for IDB put+commit survival across reload, with a
 * busy page (rAF loop + allocations) to mimic the game's teardown pressure.
 * Runs N reload rounds and reports per-trigger survival counts. */
import { chromium } from "playwright";

const ROUNDS = 10;
const browser = await chromium.launch();
const page = await browser.newPage();
await page.route("http://probe.test/**", (route) => route.fulfill({ contentType: "text/html", body: "<!doctype html><title>probe</title>" }));
await page.goto("http://probe.test/");

const survived = { beforeunload: 0, vis: 0, pagehide: 0 };

for (let round = 0; round < ROUNDS; round++) {
  await page.evaluate(async (r) => {
    const open = indexedDB.open("probe", 1);
    await new Promise<void>((resolve, reject) => {
      open.onupgradeneeded = () => open.result.createObjectStore("s");
      open.onsuccess = () => resolve();
      open.onerror = () => reject(open.error);
    });
    const db = open.result;
    // Busy-page simulation: a rAF loop with allocations, like the game's frame loop.
    let junk: number[][] = [];
    const spin = () => {
      junk.push(new Array(1000).fill(r));
      if (junk.length > 50) junk = [];
      requestAnimationFrame(spin);
    };
    requestAnimationFrame(spin);
    const value = { round: r, blob: new Array(2000).fill([12345, 42]) }; // ~game-blob sized
    const flush = (tag: string) => {
      try {
        const tx = db.transaction("s", "readwrite");
        tx.objectStore("s").put(value, `${tag}-${r}`);
        tx.commit();
      } catch {
        /* count as lost */
      }
    };
    window.addEventListener("beforeunload", () => flush("beforeunload"));
    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "hidden") flush("vis");
    });
    window.addEventListener("pagehide", () => flush("pagehide"));
  }, round);

  await page.reload();

  const found = await page.evaluate(async (r) => {
    const open = indexedDB.open("probe", 1);
    await new Promise<void>((resolve) => {
      open.onsuccess = () => resolve();
    });
    const db = open.result;
    const has = (key: string) =>
      new Promise<boolean>((resolve) => {
        const req = db.transaction("s").objectStore("s").get(key);
        req.onsuccess = () => resolve(req.result !== undefined);
        req.onerror = () => resolve(false);
      });
    const result = {
      beforeunload: await has(`beforeunload-${r}`),
      vis: await has(`vis-${r}`),
      pagehide: await has(`pagehide-${r}`)
    };
    db.close();
    return result;
  }, round);

  if (found.beforeunload) survived.beforeunload++;
  if (found.vis) survived.vis++;
  if (found.pagehide) survived.pagehide++;
}

console.log(`out of ${ROUNDS} reloads:`, JSON.stringify(survived));
await browser.close();

