import { calmDaytime, expect, test } from "./helpers";

/* TEMPORARY diagnostic spec — not committed. Reproduces the flaky
 * plain-reload persistence flow and dumps the flushWrite debug markers. */
test("DEBUG plain-reload flush diagnostics", async ({ gamePage: page }) => {
  await calmDaytime(page);
  await page.waitForTimeout(500);
  const moved = await page.evaluate(() => {
    const engine = window.__monecraft!.engine;
    engine.dispatch({ type: "moveStack", from: 0, to: 20 });
    const slot = engine.state.inventory[20];
    return { id: slot.id, count: slot.count };
  });
  expect(moved.id).not.toBeNull();

  await page.reload();
  await page.waitForFunction(() => window.__monecraft !== undefined, undefined, { timeout: 30000 });

  const diag = await page.evaluate(async () => {
    const markers = {
      flush: localStorage.getItem("dbg_flush"),
      flush2: localStorage.getItem("dbg_flush2")
    };
    const record = await new Promise((resolve) => {
      const open = indexedDB.open("monecraft");
      open.onsuccess = () => {
        const db = open.result;
        try {
          const session = JSON.parse(sessionStorage.getItem("monecraft_active_session")!) as { worldId: string };
          const req = db.transaction("worldSaves", "readonly").objectStore("worldSaves").get(session.worldId);
          req.onsuccess = () => {
            db.close();
            resolve(req.result === undefined ? "MISSING" : "present");
          };
          req.onerror = () => {
            db.close();
            resolve("get-error");
          };
        } catch (error) {
          db.close();
          resolve("tx-threw: " + String(error));
        }
      };
      open.onerror = () => resolve("open-error");
    });
    const slot = window.__monecraft!.engine.state.inventory[20];
    return { markers, record, slot: { id: slot.id, count: slot.count } };
  });
  console.log("DIAG " + JSON.stringify(diag));
});

