const record = await new Promise((resolve) => {
  const open = indexedDB.open("monecraft");
  open.onsuccess = () => {
    const db = open.result;
    try {
      const session = JSON.parse(sessionStorage.getItem("monecraft_active_session")!) as { worldId: string };
      const store = db.transaction("worldSaves", "readonly").objectStore("worldSaves");
      const get = (key: string) =>
        new Promise<string>((res) => {
          const req = store.get(key);
          req.onsuccess = () => res(req.result === undefined ? "MISSING" : "present");
          req.onerror = () => res("get-error");
        });
      void Promise.all([get(session.worldId), get("probe-bu"), get("probe-vis"), get("probe-ph")]).then(([world, bu, vis, ph]) => {
        db.close();
        resolve({ world, bu, vis, ph });
      });
    } catch (error) {
      db.close();
      resolve("tx-threw: " + String(error));
    }
  };
  open.onerror = () => resolve("open-error");
});
// Clean the probe keys so repeats don't read a previous round's survivors.
await new Promise((resolve) => {
  const open = indexedDB.open("monecraft");
  open.onsuccess = () => {
    const db = open.result;
    const tx = db.transaction("worldSaves", "readwrite");
    for (const tag of ["bu", "vis", "ph"]) tx.objectStore("worldSaves").delete("probe-" + tag);
    tx.oncomplete = () => {
      db.close();
      resolve(null);
    };
  };
});

