  return { opaque: buffers.opaque, glass: buffers.glass };
}

function buildGeometryBuffers(
  world: VoxelWorld,
  minX: number,
  maxX: number,
  minZ: number,
  maxZ: number,
  minY: number,
  maxY: number,
  splitGlass: boolean
): { opaque: THREE.BufferGeometry; glass: THREE.BufferGeometry } {
  const opaque = createBuffers();
  const glass = createBuffers();

  const clampedMinX = Math.max(0, minX);
  const clampedMaxX = Math.min(world.sizeX - 1, maxX);
  const clampedMinZ = Math.max(0, minZ);
  const clampedMaxZ = Math.min(world.sizeZ - 1, maxZ);
  const clampedMinY = Math.max(0, minY);
  const clampedMaxY = Math.min(world.sizeY - 1, maxY);

  const pushVertex = (
    buffers: GeometryBuffers,
    x: number,
    y: number,
    z: number,
    nx: number,
    ny: number,
    nz: number,
    color: [number, number, number],
    u: number,
    v: number,
    light: [number, number]
  ) => {
    buffers.positions.push(x, y, z);
    buffers.normals.push(nx, ny, nz);
    buffers.colors.push(color[0], color[1], color[2]);
    buffers.uvs.push(u, v);
    buffers.lights.push(light[0], light[1]);
  };
  const materialTint = (ny: number): [number, number, number] => {
    const shade = ny > 0 ? 1 : ny < 0 ? 0.95 : 0.9;
    return [shade, shade, shade];
  };

  // Light hitting a face comes from the voxel the face opens into (its outward
  // neighbor), sampled flat across the face like the existing AO. Returns
  // (skyExposure, blockLight) normalized to 0..1.
  const sampleFaceLight = (x: number, y: number, z: number): [number, number] => {
    return [world.getSky(x, y, z) / MAX_LIGHT, world.getBlockLight(x, y, z) / MAX_LIGHT];
  };

  const tileUV = (block: number, ny: number): [number, number, number, number] => {
    const face = ny > 0 ? "top" : ny < 0 ? "bottom" : "side";
    const tile = tileIndexFor(block, face);
    const col = tile % ATLAS_COLUMNS;
    const row = Math.floor(tile / ATLAS_COLUMNS);
    const rows = ATLAS_ROWS;
    const pad = 0.0008;
    const u0 = col / ATLAS_COLUMNS + pad;
    const v0 = row / rows + pad;
    const u1 = (col + 1) / ATLAS_COLUMNS - pad;
    const v1 = (row + 1) / rows - pad;
    return [u0, v0, u1, v1];
  };

  const faceOcclusion = (x: number, y: number, z: number, nx: number, ny: number, nz: number): number => {
    const ax = nz;
    const ay = 0;
    const az = -nx;
    const bx = 0;
    const by = 1;
    const bz = 0;

    const sx = x + nx;
    const sy = y + ny;
    const sz = z + nz;

    let occ = 0;
    if (world.isSolid(sx + ax, sy + ay, sz + az)) occ += 1;
    if (world.isSolid(sx - ax, sy - ay, sz - az)) occ += 1;
    if (world.isSolid(sx + bx, sy + by, sz + bz)) occ += 1;
    if (world.isSolid(sx - bx, sy - by, sz - bz)) occ += 1;
    return Math.max(0.8, 1 - occ * 0.06);
  };

  const pushBlockCuboid = (
    target: GeometryBuffers,
    block: number,
    x: number,
    y: number,
    z: number,
    minX: number,
    maxX: number,
    minY: number,
    maxY: number,
    minZ: number,
    maxZ: number
  ) => {
    for (const face of FACE_DEFS) {
      const nx = face.dir[0];
      const ny = face.dir[1];
      const nz = face.dir[2];
      const color = materialTint(ny);
      const light = sampleFaceLight(x + nx, y + ny, z + nz);
      const [u0, v0, u1, v1] = tileUV(block, ny);
      const corners = face.corners.map(([cx, cy, cz]) => [x + (cx ? maxX : minX), y + (cy ? maxY : minY), z + (cz ? maxZ : minZ)] as const);
      const [a, b, c, d] = corners;
      pushVertex(target, ...a, nx, ny, nz, color, u0, v1, light);
      pushVertex(target, ...b, nx, ny, nz, color, u0, v0, light);
      pushVertex(target, ...c, nx, ny, nz, color, u1, v0, light);
      pushVertex(target, ...a, nx, ny, nz, color, u0, v1, light);
      pushVertex(target, ...c, nx, ny, nz, color, u1, v0, light);
      pushVertex(target, ...d, nx, ny, nz, color, u1, v1, light);
    }
  };

  for (let y = clampedMinY; y <= clampedMaxY; y += 1) {
    for (let z = clampedMinZ; z <= clampedMaxZ; z += 1) {
      for (let x = clampedMinX; x <= clampedMaxX; x += 1) {
        const block = world.get(x, y, z);
        if (block === BlockId.Air) continue;
        const target = splitGlass && block === BlockId.Glass ? glass : opaque;
        if (isDoorBlock(block)) {
          const bounds = doorBounds(block)!;
          pushBlockCuboid(target, block, x, y, z, bounds.minX, bounds.maxX, 0, 1, bounds.minZ, bounds.maxZ);
          continue;
        }
        // Redstone overlays are small floor-mounted boxes (flat wire, a lever
        // base, a torch stub) — like doors, they mesh as inset cuboids with no
        // neighbor culling either way.
        if (isRedstoneOverlay(block)) {
          const bounds = redstoneBounds(block)!;
          pushBlockCuboid(target, block, x, y, z, bounds.minX, bounds.maxX, bounds.minY, bounds.maxY, bounds.minZ, bounds.maxZ);
          continue;
        }
        for (const face of FACE_DEFS) {
          const nx = face.dir[0];
          const ny = face.dir[1];
          const nz = face.dir[2];
          const neighbor = world.get(x + nx, y + ny, z + nz);
          if (block === BlockId.Water || block === BlockId.Glass) {
            if (neighbor === block) continue;
          } else if (neighbor !== BlockId.Glass && !isDoorBlock(neighbor) && world.isSolid(x + nx, y + ny, z + nz)) {
            continue;
          }

          const base = materialTint(ny);
          const ao = faceOcclusion(x, y, z, nx, ny, nz);
          const color: [number, number, number] = [base[0] * ao, base[1] * ao, base[2] * ao];
          const light = sampleFaceLight(x + nx, y + ny, z + nz);
          const [u0, v0, u1, v1] = tileUV(block, ny);

          const a = face.corners[0];
          const b = face.corners[1];
          const c = face.corners[2];
          const d = face.corners[3];

          pushVertex(target, x + a[0], y + a[1], z + a[2], nx, ny, nz, color, u0, v1, light);
          pushVertex(target, x + b[0], y + b[1], z + b[2], nx, ny, nz, color, u0, v0, light);
          pushVertex(target, x + c[0], y + c[1], z + c[2], nx, ny, nz, color, u1, v0, light);
          pushVertex(target, x + a[0], y + a[1], z + a[2], nx, ny, nz, color, u0, v1, light);
          pushVertex(target, x + c[0], y + c[1], z + c[2], nx, ny, nz, color, u1, v0, light);
          pushVertex(target, x + d[0], y + d[1], z + d[2], nx, ny, nz, color, u1, v1, light);
        }
      }
    }
  }

  return { opaque: createGeometry(opaque), glass: createGeometry(glass) };
}

