    expect(emission(BlockId.Stone)).toBe(0);
    expect(emission(BlockId.Glass)).toBe(0);
  });

  test("lava blocks sky light (it is opaque) while still emitting", () => {
    expect(isLightBlocker(BlockId.Lava)).toBe(true);
  });
});

