183	    // Breaking a kelp cell breaks the whole stalk above it (each cell drops),
184	    // and a submerged stalk refills with water — never air — so harvesting
185	    // doesn't leave air pockets in the ocean. The targeted cell's own drop
186	    // rides the shared addBlockDrop call below.
187	    let top = by;
188	    while (world.get(bx, top + 1, bz) === BlockId.Kelp) top += 1;
189	    const fill = world.get(bx, top + 1, bz) === BlockId.Water ? BlockId.Water : BlockId.Air;
190	    for (let y = by; y <= top; y += 1) {
191	      state.blockChanges.set(bx, y, bz, fill);
192	      if (!creative && !predict && y > by) addBlockDrop(player, BlockId.Kelp, rng, tool);
193	    }
194	  } else {
195	    state.blockChanges.set(bx, by, bz, BlockId.Air);
196	  }
197	  // Creative breaks for free: no tool wear, no drops, no XP. A predicted
198	  // break skips them too — the server owns them and its deltas deliver.
199	  if (tool && !creative && !predict) player.inventory = consumeToolDurability(player.inventory, player.selectedSlot, 1, rng) ?? player.inventory;
200	  if (!creative && !predict) {
201	    addBlockDrop(player, targetBlock as BlockId, rng, tool); // Fortune on the tool multiplies ore drops
202	    awardXp(player, xpForBlock(targetBlock as BlockId), emit); // ore blocks grant XP; everything else is 0
203	  }
