210	export function placeSelectedBlock(state: GameState, player: PlayerState, emit: EmitGameEvent): void {
211	  if (!canEditBlocks(player.gameMode)) return; // Adventure and Spectator can't place
212	  const { world } = state;
213	  const origin = eyePosition(player, scratchEye);
214	  const direction = lookDirection(player.yaw, player.pitch, scratchDir);
215	  const result = voxelRaycast(world, origin, direction, MINE_REACH);
216	  if (!result) return;
217	
218	  const tx = result.previous.x;
219	  const ty = result.previous.y;
220	  const tz = result.previous.z;
221	  if (!world.inBounds(tx, ty, tz)) return;
222	  const replacedBlock = world.get(tx, ty, tz);
223	  if (replacedBlock !== BlockId.Air && replacedBlock !== BlockId.Water) return;
224	
225	  const slot = player.inventory[player.selectedSlot];
226	  if (!slot || !slot.id || slot.kind !== "block" || slot.count <= 0 || slot.blockId === undefined) return;
227	  if (slot.blockId === BlockId.Bedrock) return;
228	
229	  // Creative builds without spending the held stack (so no take, no refund).
230	  const consume = !freeBuild(player.gameMode);
231	  if (consume) {
232	    const afterTake = adjustSlotCount(player.inventory, slot.id, -1, player.selectedSlot);
233	    if (!afterTake) return;
234	    player.inventory = afterTake;
235	  }
236	  let replacedUpper: BlockId | null = null;
237	  if (slot.id === "door") {
238	    const support = world.get(tx, ty - 1, tz);
239	    replacedUpper = world.get(tx, ty + 1, tz) as BlockId;
240	    if (ty + 1 >= world.sizeY || (replacedUpper !== BlockId.Air && replacedUpper !== BlockId.Water) || !world.isSolid(tx, ty - 1, tz) || isDoorBlock(support)) {
241	      if (consume) player.inventory = adjustSlotCount(player.inventory, slot.id, 1, player.selectedSlot) ?? player.inventory;
242	      return;
243	    }
244	    const facing = doorFacingFromYaw(player.yaw);
245	    state.blockChanges.set(tx, ty, tz, doorBlock(facing, false, false));
246	    state.blockChanges.set(tx, ty + 1, tz, doorBlock(facing, false, true));
247	  } else {
248	    state.blockChanges.set(tx, ty, tz, slot.blockId);
249	  }
250	  if (collidesAt(world, player.position, PLAYER_HALF_WIDTH, PLAYER_HEIGHT)) {
251	    state.blockChanges.set(tx, ty, tz, replacedBlock as BlockId);
252	    if (replacedUpper !== null) state.blockChanges.set(tx, ty + 1, tz, replacedUpper);
253	    if (consume) player.inventory = adjustSlotCount(player.inventory, slot.id, 1, player.selectedSlot) ?? player.inventory;
254	    return;
255	  }
256	
257	  // A placed chest gets a fresh, empty block-entity store.
258	  if (slot.blockId === BlockId.Chest) {
259	    state.containers.set(
260	      world.index(tx, ty, tz),
261	      Array.from({ length: CHEST_SLOTS }, () => createEmptySlot())
262	    );
263	  }
264	
265	  state.worldMeshDirty = true;
266	  emit({ type: "blockPlaced", blockId: slot.blockId, x: tx, y: ty, z: tz });
