19	import type { EmitGameEvent, GameState, RedstoneState } from "../state";
20	import { primeTnt } from "./explosion";
21	
22	/**
23	 * Redstone-lite power simulation. Binary signal: on-state sources (lever,
24	 * pressed button/plate, lit redstone torch) power their six face neighbors;
25	 * wire carries the signal up to REDSTONE_WIRE_RANGE wire-to-wire hops (with
26	 * one-block slope climbing) and powers everything it touches. A redstone
27	 * torch is an inverter — it turns off while its support block is powered,
28	 * and never powers its own support, so it cannot feed itself.
29	 *
30	 * The whole pass re-derives power from the block grid at a fixed cadence
31	 * (REDSTONE_TICK_SECONDS) and writes only actual state changes, so a stable
32	 * circuit costs nothing per pass. All effects are block-id swaps through the
33	 * blockChanges.set chokepoint (relight + save diff + net journal for free);
34	 * per-cell bookkeeping self-heals, so mining, explosions, and server-applied
35	 * edits need zero redstone awareness. Runs server-side only in online worlds:
36	 * replicas early-return before world systems and receive the resulting block
37	 * deltas through the tick journal like any other edit.
38	 */
39	
40	export function createRedstoneState(): RedstoneState {
41	  return { cells: new Set(), buttonTimers: new Map(), prevDoorPowered: new Set(), timer: 0 };
42	}
43	
44	/**
45	 * Boot-time seeding: every redstone block is craft-only, hence player-placed,
46	 * hence present in the save's block diff — scanning it recovers the full
47	 * component set with no persistence of our own.
48	 */
49	export function seedRedstoneCells(state: GameState): void {
50	  for (const [index, block] of state.blockChanges.changes()) {
51	    if (isRedstoneBlock(block)) state.redstone.cells.add(index);
52	  }
53	}
54	
55	/** The placement seam: track a freshly placed component (any redstone id). */
56	export function trackRedstoneCell(state: GameState, x: number, y: number, z: number): void {
57	  state.redstone.cells.add(state.world.index(x, y, z));
58	}
59	
60	/** Right-click on a lever: flip it and let the next pass propagate. */
61	export function toggleLever(state: GameState, emit: EmitGameEvent, x: number, y: number, z: number): boolean {
62	  const block = state.world.get(x, y, z);
63	  if (!isLever(block)) return false;
64	  const next = isRedstoneOn(block) ? redstoneOff(block as BlockId) : redstoneOn(block as BlockId);
65	  state.blockChanges.set(x, y, z, next);
66	  state.redstone.cells.add(state.world.index(x, y, z));
67	  state.worldMeshDirty = true;
68	  emit({ type: "leverToggled", on: isRedstoneOn(next) });
69	  return true;
70	}
71	
72	/** Right-click on a button: press it and arm the pop-back timer. */
73	export function pressButton(state: GameState, emit: EmitGameEvent, x: number, y: number, z: number): boolean {
74	  const block = state.world.get(x, y, z);
75	  if (!isRedstoneButton(block)) return false;
76	  // Already pressed: consume the click (re-pressing does not extend the timer).
77	  if (isRedstoneOn(block)) return true;
78	  state.blockChanges.set(x, y, z, redstoneOn(block as BlockId));
79	  const index = state.world.index(x, y, z);
80	  state.redstone.cells.add(index);
81	  state.redstone.buttonTimers.set(index, REDSTONE_BUTTON_PRESS_SECONDS);
82	  state.worldMeshDirty = true;
83	  emit({ type: "buttonPressed" });
84	  return true;
85	}
86	
87	/** Feet cells currently standing on the ground — players and mobs both press plates. */
88	function collectOccupiedCells(state: GameState): Set<number> {
89	  const occupied = new Set<number>();
90	  const { world } = state;
91	  for (const player of state.players.values()) {
92	    const x = Math.floor(player.position.x);
93	    const y = Math.floor(player.position.y + 0.05);
94	    const z = Math.floor(player.position.z);
95	    if (world.inBounds(x, y, z)) occupied.add(world.index(x, y, z));
96	  }
97	  for (const mob of state.mobs) {
98	    // MobState.position is the body center; halfHeight brings us to the feet.
99	    const x = Math.floor(mob.position.x);
100	    const y = Math.floor(mob.position.y - mob.halfHeight + 0.05);
101	    const z = Math.floor(mob.position.z);
102	    if (world.inBounds(x, y, z)) occupied.add(world.index(x, y, z));
103	  }
104	  return occupied;
105	}
106	
107	const HORIZONTAL: ReadonlyArray<readonly [number, number]> = [
108	  [1, 0],
109	  [-1, 0],
110	  [0, 1],
111	  [0, -1]
112	];
113	
114	const FACES: ReadonlyArray<readonly [number, number, number]> = [
115	  [1, 0, 0],
116	  [-1, 0, 0],
117	  [0, 1, 0],
118	  [0, -1, 0],
119	  [0, 0, 1],
120	  [0, 0, -1]
121	];
122	
123	export function tickRedstone(state: GameState, dt: number, emit: EmitGameEvent): void {
124	  const rs = state.redstone;
125	  rs.timer += dt;
126	  if (rs.timer < REDSTONE_TICK_SECONDS) return;
127	  rs.timer = 0;
128	
129	  const { world } = state;
130	  const sizeXZ = world.sizeX * world.sizeZ;
131	  const xOf = (index: number) => index % world.sizeX;
132	  const zOf = (index: number) => Math.floor(index / world.sizeX) % world.sizeZ;
133	  const yOf = (index: number) => Math.floor(index / sizeXZ);
134	  let changed = false;
135	  const write = (x: number, y: number, z: number, block: BlockId) => {
136	    state.blockChanges.set(x, y, z, block);
137	    changed = true;
138	  };
139	
140	  // Phase 1 — inputs & self-heal. Deleting while iterating a Set is safe.
141	  const occupied = collectOccupiedCells(state);
142	  for (const index of rs.cells) {
143	    const block = world.blocks[index];
144	    if (!isRedstoneBlock(block)) {
145	      // Mined, exploded, or overwritten (locally or by a server delta): forget it.
146	      rs.cells.delete(index);
147	      rs.buttonTimers.delete(index);
148	      continue;
149	    }
150	    const x = xOf(index);
151	    const y = yOf(index);
152	    const z = zOf(index);
153	    // An overlay whose support vanished pops off (no drop — whatever removed
154	    // the support, e.g. an explosion, would have vaporized the component too;
155	    // direct mining cascades the drop in mining.ts before this runs).
156	    if (isRedstoneOverlay(block)) {
157	      const support = world.get(x, y - 1, z);
158	      if (!world.isSolid(x, y - 1, z) || isRedstoneOverlay(support) || isDoorBlock(support)) {
159	        write(x, y, z, BlockId.Air);
160	        rs.cells.delete(index);
161	        rs.buttonTimers.delete(index);
162	        continue;
163	      }
164	    }
165	    if (isPressurePlate(block)) {
166	      const pressed = occupied.has(index);
167	      if (pressed !== isRedstoneOn(block)) {
168	        write(x, y, z, pressed ? redstoneOn(block as BlockId) : redstoneOff(block as BlockId));
169	        emit({ type: "plateToggled", on: pressed });
170	      }
171	    }
172	    if (block === BlockId.RedstoneButtonOn) {
173	      // A missing timer entry (a save written mid-press just reloaded) heals
174	      // by popping the button back immediately. The epsilon absorbs float
175	      // drift so the pop lands on the expected pass, not one late.
176	      const left = rs.buttonTimers.get(index);
177	      if (left === undefined || left - REDSTONE_TICK_SECONDS <= 1e-9) {
178	        write(x, y, z, BlockId.RedstoneButton);
179	        rs.buttonTimers.delete(index);
180	      } else {
181	        rs.buttonTimers.set(index, left - REDSTONE_TICK_SECONDS);
182	      }
183	    }
184	  }
185	
