describe("audio director", () => {
  test("does nothing before unlock", () => {
    const fake = createFakeGraph();
    const director = createAudioDirector({ createGraph: () => fake.graph });
    director.handleEvent({ type: "blockBroken", blockId: BlockId.Stone, x: 0, y: 0, z: 0 });
    expect(fake.played.length).toBe(0);
  });

  test("routes block events through the material mapping", async () => {
    const { director, played } = await createUnlockedDirector();
    director.handleEvent({ type: "blockBroken", blockId: BlockId.Cobblestone, x: 0, y: 0, z: 0 });
    director.handleEvent({ type: "blockPlaced", blockId: BlockId.Planks, x: 0, y: 0, z: 0 });
    director.handleEvent({ type: "doorToggled", open: true });
    director.handleEvent({ type: "playerHurt" });
    expect(played[0].def).toBe(BREAK_SOUNDS.stone);
    expect(played[1].def).toBe(PLACE_SOUNDS.wood);
    expect(played[2].def).toBe(PLACE_SOUNDS.wood);
    expect(played[2].opts.gain).toBe(0.8);
    expect(played[3].def).toBe(HURT_SOUND);
  });

  test("placing a vehicle thunks like wood; a failed placement plays the denial cue", async () => {
    const { director, played } = await createUnlockedDirector();
    director.handleEvent({ type: "vehiclePlaced", kind: "raft" });
    director.handleEvent({ type: "vehiclePlaceFailed" });
    expect(played[0].def).toBe(PLACE_SOUNDS.wood);
    expect(played[1].def).toBe(VEHICLE_DENIED_SOUND);
  });

  test("landing volume scales with impact", async () => {
    const { director, played } = await createUnlockedDirector();
    director.handleEvent({ type: "landed", impact: 3 });
    director.handleEvent({ type: "landed", impact: 20 });
    expect(played[0].def).toBe(LAND_SOUND);
    expect(played[0].opts.gain!).toBeLessThan(played[1].opts.gain!);
  });

